def get_ludic(n):
    """Return a list of lucid numbers smaller than or equal to n."""
    res = []
    i = 2
    while i <= n:
        # Append numbers that are the product of unique earlier squared numbers
        res.append(i)
        for j in range(i, n // i + 1):
            res.append(j * i)
        i += 1
    return sorted(list(set(res)))

