def bell_Number(n):
    # Initialize the factorial function
    def factorial(x):
        if x <= 1:
            return 1
        return x * factorial(x-1)

    # Calculate the bell number function
    bell = [0] * (n + 1)
    bell[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            bell[i] += bell[j] * factorial(i - 1)

    # Return the calculated bell number
    return bell[n]

# Test the function
