def max_sum_of_three_consecutive(nums, n):
    # Initialize base cases
    dp = [0] * (n + 1)

    # Fill DP table
    for i in range(1, n + 1):
        dp[i] = max(dp[i - 1], nums[i] + dp[i - 3])

    # The maximum sum consists of the two possible endings: ending with the last two elements or ending with the first three elements
    return max(dp[-1], dp[-3])

