def max_sum_of_three_consecutive(numbers, n):
    if n < 3:
        return 0

    max_sum = [0] * (n + 1)
    max_sum[2] = numbers[0] + numbers[1]
    max_sum[3] = max(numbers[0] + numbers[1], numbers[1] + numbers[2], numbers[1] + numbers[2])

    for i in range(4, n + 1):
        max_sum[i] = max(max_sum[i - 1], max_sum[i - 2], max_sum[i - 3]) + numbers[i - 1]

    return max_sum[n]

