def max_sum_of_three_consecutive(nums):
    if len(nums) < 3:
        return 0

    dp = [nums[0], max(nums[0] + nums[1], nums[0]), max(nums[0] + nums[1] + nums[2], nums[0])]  # Initialize the dynamic programming table

    for i in range(3, len(nums)):
        dp.append(max(nums[i] + nums[i - 1] + nums[i - 2], nums[i], dp[i - 1]))  # Update the dynamic programming table

    return dp[-1]  # Return the maximum sum

