def lcs_of_three(s1, s2, s3, l1, l2, l3):
    # Initialize the 3D DP table with zeros
    dp_matrix = [[[0 for _ in range(l3 + 1)] for _ in range(l2 + 1)] for _ in range(l1 + 1)]

    # Fill the DP table
    for i in range(1, l1 + 1):
        for j in range(1, l2 + 1):
            for k in range(1, l3 + 1):
                if s1[i - 1] == s2[j - 1] == s3[k - 1]:
                    dp_matrix[i][j][k] = dp_matrix[i - 1][j - 1][k - 1] + 1
                else:
