def pack_consecutive_duplicates(arr):
    if len(arr) == 0:
        return []

    # Initialize a result list and a mapping to store the last occurrence index of each element
    result = []
    mapping = {}

    for index, element in enumerate(arr):
        if element in mapping:
            # If the element is already in the mapping, it means we have consecutive duplicates
            # Add the previously identified sublist to the result and update the mapping.
            result.append(arr[mapping[element]:index])
            mapping[element] = index
        else:
            # If the element is not in the mapping, it means we are encountering a new element
            # Add the element to the result.
            mapping[element] = index
            result.append([element])

    # Append the last sublist if needed
    if mapping and mapping[arr[-1]] < len(arr) - 1:
        result.append(arr[mapping[arr[-1]] + 1:])

    return result

