    c_max = max(r, g, b)
    c_min = min(r, g, b)
    diff = c_max - c_min

    if c_max == 0:
        h = 0
    elif c_max == r:
        h = (60 * ((g - b) / diff) + 360) % 360
    elif c_max == g:
        h = (60 * ((b - r) / diff) + 120) % 360
    elif c_max == b:
        h = (60 * ((r - g) / diff) + 240) % 360

    if c_max == 0:
        s = 0
    else:
        s = (diff / c_max) * 100

    v = c_max * 100

    return (h, s, v)

