def rgb_to_hsv(r, g, b):
    """
    Convert RGB color to HSV color.

    Args:
    r (int): The red component of the color (0-255).
    g (int): The green component of the color (0-255).
    b (int): The blue component of the color (0-255).

    Returns:
    tuple: A tuple containing HSV values (h, s, v).
    """
    min_val = min(r, g, b)
    max_val = max(r, g, b)
    delta = max_val - min_val
    if delta == 0:
        return (0, 0, max_val)

    hue = ((max_val - g) / delta) % 6
    if r == max_val:
        s = (delta / max_val) * 100
    else:
        if g == max_val:
            s = (delta / max_val) * 100
        else:
            s = (delta / max_val) * 100
    v = max_val * 100
    return (hue, s, v)

