def count_Rotation(arr, n):
    # Define a recursive function to return the index of the smallest element
    def find_minimum(A, left, right):
        if left == right:
            return left
        mid = (left+right)//2
        if (mid==0 or A[mid]<A[mid-1]) and (mid==n-1 or A[mid]<A[mid+1]):
            return mid
        elif A[mid] >= A[left]:
            return find_minimum(A, mid+1, right)
        return find_minimum(A, left, mid-1)

    # Find the index of the smallest element and then right rotate n - index times
    return n - find_minimum(arr, 0, n-1)
