import heapq

def nth_super_ugly_number(n, primes):
    ugly_numbers = [1]  # initialized with the first ugly number
    heap = [1*prime for prime in primes]  # create a heap with first product of all primes

    for _ in range(n-1):
        current_ugly = heapq.heappop(heap)  # get the smallest ugly number
        ugly_numbers.append(current_ugly)  # add it to the list of ugly numbers
        for prime in primes:
            next_ugly = current_ugly * prime
            if next_ugly not in ugly_numbers:
                heapq.heappush(heap, next_ugly)  # add the next product to the heap

    return ugly_numbers[-1]  # return the nth ugly number

