def sum_of_odd_Factors(num):
    if num < 2:
        return 0  # As even numbers are factors of itself and 2 is the smallest even prime number
    odd_factors = 0
    for i in range(1, int(num**0.5) + 1):
        if num % i == 0:
            if i % 2 != 0:
                odd_factors += i
            if (num // i) % 2 != 0 and (num // i) != i:
                odd_factors += num // i
    return odd_factors

