    arr.sort()  # sort the array to enable efficient consecutive check later
    current_length = 1  # initialize the current length of the subsequence
    max_length = 1  # initialize the maximum length of the subsequence found

    for i in range(1, n):
        if arr[i] == arr[i-1] + 1:
            current_length += 1  # increment the current subsequence length
        else:
            max_length = max(max_length, current_length)  # update the maximum length if current is greater
            current_length = 1  # reset the current length to start new subsequence

    return max(max_length, current_length)  # return final maximum subsequence length

