def check(arr, n):
    def possible():
        n = len(arr)
        if n == 1 or arr[0] <= arr[n-1]:
            return True
        for i in range(1, n-1):
            if arr[i] < arr[i-1]:
                return False
        return True
    if n % 2 == 1:
