def previous_palindrome(n):
    """
    Find the previous palindrome of a specified number.

    :param n: Integer
    :return: Integer, the previous palindrome of the given number
    """
    str_n = str(n)
    for i in range(len(str_n) - 1, -1, -1):
        for j in range(i - 1, -1, -1):
            if str_n[i] == str_n[j]:
                candidate = int(str_n[:i] + str_n[j] + str_n[i:j][::-1] + str_n[j+1:])
                if candidate < n:
                    return candidate
    return n - 1

