import math

def lobb_number(n, k):
    """
    A function to compute the lobb number for n objects in k unordered groups.

    Args:
    n (int): Number of distinct objects.
    k (int): Number of unordered groups.

    Returns:
    int: Lobb number for the given values of n and k.
