def find_triplet_array(nums, target_value, n):
    nums.sort()  # Sorting the array for the two-pointer technique
    left, right = 0, n - 1

    while left < right:
        current_sum = nums[left] + nums[right]

        if current_sum == target_value:
            return (nums[left], nums[right], nums[n - 1])  # Returning the triplet once found

        if current_sum < target_value:
            left += 1  # Adjusting left pointer to favor a higher sum
        else:
            right -= 1  # Adjusting right pointer to favor a lower sum

        while left < right and nums[left] == nums[left - 1]:
            left += 1  # Adjusting left pointer to avoid duplicate triplets
        while left < right and nums[right] == nums[right + 1]:
            right -= 1  # Adjusting right pointer to avoid duplicate triplets

    return None  # Returning None if no such triplet exists

