    for i in range(len(arr)):
        left = i + 1  # Starting index of the remaining part of the array
        right = len(arr) - 1  # Ending index of the remaining part of the array

        while left < right:
            # Calculate the sum of the current triplet
            current_sum = arr[i] + arr[left] + arr[right]

            # Check if the current sum matches the target sum
            if current_sum == target_val:
                return (arr[i], arr[left], arr[right])

            # If the sum is less than the target sum, move the left index to the right
            elif current_sum < target_val:
