def max_product(arr):
    """
    Find a pair with the highest product from a given array of integers.

    Args:
    arr (list): A list of integers.

    Returns:
    tuple: A tuple containing the pair with the highest product.
    """
    if len(arr) < 2:
        return None
    max1 = max2 = max(arr)
    min1 = min2 = min(arr)

    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num
        elif num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    return (max1, max2) if max1 * max2 > min1 * min2 else (min1, min2)

