def rencontres_number(n, k):
    # Base case: There is only one way to arrange 0 people in k groups if k > 0
    if k == 0:
        return 0
    # Base case: There is only one way to arrange k people in 1 group
    elif k == 1:
        return n
    # Recursive case: The number of ways to arrange n people in k groups is n * (n-1) * (n-2) * ... * (n-(k-1)) + (n-1) * (n-2) * ... * (n-(k-1))
    else:
        return n * rencontres_number(n-1, k-1) + rencontres_number(n-1, k)

