def dealnnoy_num(n, k):
    if n == 0:
        return 0
    if k ==0:
        return 1

    # Initialize the base cases
    table = [[0 for _ in range(k+1)] for _ in range(n+1)]

    # The nth Delannoy number is the sum of the (n-1)th and the nth Delannoy number of the (n-2)th row
    for i in range(n+1):
        table[i][0] = 1
        for j in range(1, k+1):
            table[i][j] = table[i-1][j] + table[i-1][j-1]

    return table[n][k]

