from collections import Counter

def most_common_elem(text, n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n == 0:
        return []

    # Count the frequency of elements in the text
    counter = Counter(text)

    # Return the top n most common elements along with their counts
    return list(counter.most_common(n))

