def subset(arr, K):
    """Find the minimum number of subsets with distinct elements."""
    if len(arr) < K:
        return -1

    min_subsets = 0
    visited = set()

    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] != arr[j] and not (arr[i] in visited or arr[j] in visited):
                visited.add(arr[i])
                visited.add(arr[j])
                min_subsets += 1

    return min_subsets

