def get_noOfways(n):
    if n <= 2:
        return 1
    # solution for n tiles divided into squares and stones
    s = int(n*(n+1)/2)
    if s%2 != 0:
        return 0
    # Fibonacci series
    fib = [0, 1]
    for i in range(2, s//2 + 1):
        fib.append(fib[i-1] + fib[i-2])
    used = set([1])
    stack = [[s, used]]
    while stack:
        n, used = stack.pop()
        for a in fib:
            if a == 1:
                continue
            if (n-a in used):
                continue
            if a < n:
                stack.append([n-a, used.union([a])])
    return len(used)

